pub fn solve(input: serde_json::Value) -> serde_json::Value {
    match input {
        serde_json::Value::Number(n) => {
            let signed_cents: i64 = match n {
                serde_json::Number::Signed(s) => s.as_i64().unwrap(),
                serde_json::Number::Unsigned(u) => u.as_u64().unwrap() as i64,
                _ => 0,
            };

            let pounds = signed_cents / 100;
            let fractional = signed_cents % 100;

            let mut result = String::new();
            if pounds < 0 {
                result.push('-');
            }
            result.push_str(&format!("{:}", pounds.abs()));
            if fractional != 0 {
                result.push('.');
                result.push_str(&format!("{:02}", fractional));
            } else {
                result.push('.');
                result.push('0');
                result.push('0');
            }

            serde_json::Value::String(result)
        }
        serde_json::Value::Array(arr) => {
            let mut result = Vec::new();
            for item in arr {
                result.push(solve(item));
            }
            serde_json::Value::Array(result)
        }
        serde_json::Value::Object(obj) => {
            let mut result = std::collections::HashMap::new();
            for (k, v) in obj {
                result.insert(k, solve(v));
            }
            serde_json::Value::Object(result)
        }
        serde_json::Value::Null => serde_json::Value::Null,
        serde_json::Value::Bool(b) => serde_json::Value::Bool(b),
    }
}
